            {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_m, ['name']), 'ratio' => '1/1', 'className' => og_cnv([og_cnv(['size-16', 'shrink-0'])])]])|noescape}
            {capture $c_1}
