          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '2', 'align' => 'center', 'class' => 'text-center', 'attrs' => og_attrs(['data-slot', 'item']), 'children' => (string) $c_3])|noescape}
        {elseif og_t(og_eq($v_layout, 'cards'))}
          {capture $c_9}
            {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_m, ['name']), 'ratio' => '1/1']])|noescape}
            {capture $c_8}
              {capture $c_6}
