                  {=og_text(og_get($v_m, ['name']))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => 'base', 'weight' => 'semibold', 'children' => (string) $c_4])|noescape}
                {capture $c_5}
                  {=og_text(og_get($v_m, ['role']))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_5])|noescape}
              {/capture}
              {=og_include('compose/Stack.latte', ['gap' => '0', 'children' => (string) $c_6])|noescape}
              {capture $c_7}
                {=og_text(og_get($v_m, ['bio']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_7])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '2', 'children' => (string) $c_8])|noescape}
          {/capture}
