        {/if}
      {/foreach}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'minimal')) ? 'grid grid-cols-2 gap-8 md:grid-cols-4' : (og_t(og_eq($v_layout, 'directory')) ? 'grid grid-cols-1 gap-4 md:grid-cols-2' : (og_t(og_eq($v_layout, 'list')) ? 'flex flex-col gap-4' : (og_t(og_eq($v_cols, '1-3')) ? 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3' : 'grid grid-cols-1 gap-4 sm:grid-cols-2 md:grid-cols-4'))))), 'attrs' => og_attrs(['data-slot', 'items']), 'children' => (string) $c_10])|noescape}
  {/if}
