{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'density' => $v_density, 'layout' => (og_t(og_eq($v_layout, 'list')) ? 'split' : 'stack'), 'media' => ['show' => og_eq($v_layout, 'list'), 'side' => 'start', 'align' => 'start'], 'landmarkLabel' => $v_landmarkLabel, 'aside' => og_markup($f_11)], 'children' => og_markup($c_12)])|noescape}
